const PATH={site:'data/site.json',about:'data/about.json',research:'data/research.json',publications:'data/publications.json',skills:'data/skills.json',education:'data/education.json',contact:'data/contact.json',appearance:'data/appearance.json',cv:'data/cv.json',languages:'data/languages.json','skill-details':'data/skill-details.json',custom:'data/custom-sections.json',access:'data/access.json'};
const SESSION='admin-unlocked-v4', ACT='admin-last-activity-v4', IDLE=20*60*1000;
let STATE={};
const VIEWS={overview:['Overview','Organise your portfolio without touching code.'],home:['Home','Hero content, identity and CV call-to-action.'],about:['About','Biography and profile presentation.'],research:['Research','Projects, publication links and downloadable PDFs.'],skills:['Skills','Categories plus dedicated detail pages for every skill.'],education:['Education','Academic timeline.'],contact:['Contact','Professional contact channels.'],custom:['Custom Sections','Add, reorder, hide and style your own portfolio sections.'],media:['Media Library','Upload, reuse and assign images and files.'],appearance:['Appearance','Colors, gradients, typography and scientific background controls.'],navigation:['Navigation','Rename, reorder, show or hide navigation items.'],languages:['Languages','Choose the supported portfolio and dashboard languages.'],cv:['CV Manager','Manage the CV PDF, editable CV source and reusable cover letter.'],security:['Security','Token hygiene, dashboard password and session controls.'],publications:['Publications','Edit publication metadata and authentic publication/PDF links.']};
function $(id){return document.getElementById(id)}
function toast(msg,error=false){const e=document.createElement('div');e.className='toast '+(error?'error':'');e.textContent=msg;$('toastWrap').appendChild(e);setTimeout(()=>e.remove(),4200)}
function esc(s){return String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function attr(s){return esc(s).replace(/\n/g,' ')}
function openModal(html){$('modal').innerHTML=html;$('modalBackdrop').classList.add('open')}
function closeModal(){$('modalBackdrop').classList.remove('open');$('modal').innerHTML=''}
$('modalBackdrop').addEventListener('click',e=>{if(e.target.id==='modalBackdrop')closeModal()});
function sha256(s){return crypto.subtle.digest('SHA-256',new TextEncoder().encode(s)).then(b=>Array.from(new Uint8Array(b)).map(x=>x.toString(16).padStart(2,'0')).join(''))}
function randHex(n=16){const a=new Uint8Array(n);crypto.getRandomValues(a);return [...a].map(x=>x.toString(16).padStart(2,'0')).join('')}
async function pbkdf2(p,salt,it=150000){const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(p),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:new Uint8Array(salt.match(/.{2}/g).map(h=>parseInt(h,16))),iterations:it,hash:'SHA-256'},key,256);return [...new Uint8Array(bits)].map(x=>x.toString(16).padStart(2,'0')).join('')}
function touch(){if(sessionStorage.getItem(SESSION)!=='1')return;sessionStorage.setItem(ACT,Date.now());clearTimeout(window.__idle);window.__idle=setTimeout(lock,IDLE)}
['click','keydown','mousemove','touchstart','scroll'].forEach(e=>addEventListener(e,touch,{passive:true}));
function lock(){sessionStorage.removeItem(SESSION);sessionStorage.removeItem(ACT);GH.setToken('');location.reload()}
async function accessData(){try{return (await GH.getJSON(PATH.access)).data||{passwordHash:''}}catch{return {passwordHash:''}}}
async function init(){
 const cfg=GH.getConfig();
 if(!GH.isConfigured()){$('setupScreen').classList.remove('hidden');return}
 const a=await accessData();STATE.access=a;
 const unlocked=sessionStorage.getItem(SESSION)==='1'&&Date.now()-Number(sessionStorage.getItem(ACT)||0)<IDLE;
 if(unlocked){touch();boot();return}
 $('passwordScreen').classList.remove('hidden');
 if(!a.passwordHash){$('passwordTitle').textContent='🔐 Create admin password';$('passwordText').textContent='First run: create a strong password. It is stored only as a salted PBKDF2 verifier in the repository.';$('confirmWrap').classList.remove('hidden');$('passwordBtn').textContent='Create & enter'}
}
$('setupForm').addEventListener('submit',async e=>{e.preventDefault();const cfg={owner:$('setupOwner').value.trim(),repo:$('setupRepo').value.trim(),branch:$('setupBranch').value.trim()||'main',token:$('setupToken').value.trim()};try{GH.setConfig(cfg);await GH.testConnection();$('setupScreen').classList.add('hidden');const a=await accessData();STATE.access=a;$('passwordScreen').classList.remove('hidden');if(!a.passwordHash){$('passwordTitle').textContent='🔐 Create admin password';$('confirmWrap').classList.remove('hidden');$('passwordBtn').textContent='Create & enter'}toast('GitHub connected ✓')}catch(err){GH.clear();$('setupError').textContent=err.message}});
$('passwordForm').addEventListener('submit',async e=>{e.preventDefault();const p=$('passwordInput').value;const d=STATE.access||{};try{if(!d.passwordHash){if(p.length<10)throw Error('Use at least 10 characters.');if(p!==$('passwordConfirm').value)throw Error('Passwords do not match.');const salt=randHex();const hash=await pbkdf2(p,salt);STATE.access={passwordHash:hash,salt,kdf:'PBKDF2',iterations:150000,version:4};await GH.putJSON(PATH.access,STATE.access,'Set dashboard password')}else{const ok=d.kdf==='PBKDF2'?await pbkdf2(p,d.salt,d.iterations||150000):await sha256(p);if(ok!==d.passwordHash)throw Error('Incorrect password.')}sessionStorage.setItem(SESSION,'1');touch();$('passwordScreen').classList.add('hidden');boot()}catch(err){$('passwordError').textContent=err.message}});
async function loadState(){const names=Object.keys(PATH).filter(k=>k!=='access');const out={};for(const n of names){try{out[n]=(await GH.getJSON(PATH[n])).data}catch{out[n]=n==='research'||n==='publications'||n==='skills'||n==='education'||n==='skill-details'||n==='custom'?[]:{}}}return out}
async function save(key,msg){
 try{
  STATE[key]=STATE[key]||{};
  await GH.putJSON(PATH[key],STATE[key],msg||`Update ${key}`);
  STATE.site.lastUpdated=new Date().toISOString();
  try{await GH.putJSON(PATH.site,STATE.site,'Update site timestamp')}catch(e){console.warn('Site timestamp update failed',e)}
  toast('Saved to GitHub ✓');
 }catch(e){toast(`Save failed: ${e.message||e}`,true);throw e}
}
async function savePath(path,obj,msg){await GH.putJSON(path,obj,msg);toast('Saved to GitHub ✓')}
async function boot(){$('shell').classList.remove('hidden');$('passwordScreen').classList.add('hidden');try{const s=await loadState();STATE={...STATE,...s};applyDashboardTheme();renderView('overview')}catch(e){toast(e.message,true);$('views').innerHTML=`<div class="card"><h2>Dashboard could not load</h2><p class="error">${esc(e.message)}</p><button class="btn" onclick="boot()">Retry</button></div>`}}
$('refreshBtn').addEventListener('click',()=>boot());$('logout').addEventListener('click',lock);$('viewSite').addEventListener('click',()=>{const c=GH.getConfig();window.open(`https://${c.owner}.github.io/${c.repo}/`,'_blank','noopener')});$('mobileMenu').addEventListener('click',()=>$('sidebar').classList.toggle('open')); addEventListener('unhandledrejection',e=>{if(e.reason)toast(e.reason.message||String(e.reason),true)});
document.querySelectorAll('.navbtn[data-view]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.navbtn').forEach(x=>x.classList.remove('active'));b.classList.add('active');$('sidebar').classList.remove('open');renderView(b.dataset.view)}));

const DASH_I18N={en:{overview:'Overview',home:'Home',about:'About',research:'Research',skills:'Skills',education:'Education',contact:'Contact',media:'Media Library',appearance:'Appearance',navigation:'Navigation',languages:'Languages',cv:'CV Manager',security:'Security',custom:'Custom Sections',publications:'Publications'},de:{overview:'Übersicht',home:'Startseite',about:'Über mich',research:'Forschung',skills:'Fähigkeiten',education:'Ausbildung',contact:'Kontakt',media:'Mediathek',appearance:'Darstellung',navigation:'Navigation',languages:'Sprachen',cv:'CV-Verwaltung',security:'Sicherheit',custom:'Benutzerdefinierte Bereiche',publications:'Publikationen'},bn:{overview:'ওভারভিউ',home:'হোম',about:'আমার সম্পর্কে',research:'গবেষণা',skills:'দক্ষতা',education:'শিক্ষা',contact:'যোগাযোগ',media:'মিডিয়া লাইব্রেরি',appearance:'ডিজাইন',navigation:'নেভিগেশন',languages:'ভাষা',cv:'CV ম্যানেজার',security:'নিরাপত্তা',custom:'কাস্টম সেকশন',publications:'প্রকাশনা'},es:{overview:'Resumen',home:'Inicio',about:'Sobre mí',research:'Investigación',skills:'Habilidades',education:'Educación',contact:'Contacto',media:'Biblioteca multimedia',appearance:'Diseño',navigation:'Navegación',languages:'Idiomas',cv:'Gestor de CV',security:'Seguridad',custom:'Secciones personalizadas',publications:'Publicaciones'},it:{overview:'Panoramica',home:'Home',about:'Chi sono',research:'Ricerca',skills:'Competenze',education:'Formazione',contact:'Contatti',media:'Libreria media',appearance:'Aspetto',navigation:'Navigazione',languages:'Lingue',cv:'Gestore CV',security:'Sicurezza',custom:'Sezioni personalizzate',publications:'Pubblicazioni'}};
function applyDashLang(){const l=localStorage.getItem('dashboard-language-v1')||'en';const d=DASH_I18N[l]||DASH_I18N.en;document.querySelectorAll('.navbtn[data-view]').forEach(b=>{const v=b.dataset.view;if(!b.dataset.icon)b.dataset.icon=b.textContent.trim()[0]||'•';const first=b.dataset.icon;b.textContent=first+' '+(d[v]||v)});$('dashLang').value=l;}
$('dashLang').addEventListener('change',e=>{localStorage.setItem('dashboard-language-v1',e.target.value);applyDashLang();const active=document.querySelector('.navbtn.active[data-view]');if(active)renderView(active.dataset.view)});

function renderView(v){
 if(!VIEWS[v])v='overview';
 $('viewTitle').textContent=VIEWS[v][0];
 $('viewSub').textContent=VIEWS[v][1];
 const fn={overview:viewOverview,home:viewHome,about:viewAbout,research:viewResearch,publications:viewPublications,skills:viewSkills,education:viewEducation,contact:viewContact,media:viewMedia,appearance:viewAppearance,navigation:viewNavigation,languages:viewLanguages,cv:viewCV,security:viewSecurity,custom:viewCustomSections}[v];
 $('views').innerHTML='';
 if(fn)fn();else toast('Editor not found: '+v,true);
 if(v!=='overview')setTimeout(()=>setupSectionEditor(v),40);
}

function setupSectionEditor(view){
 const root=$('views'); if(!root || !root.children.length)return;
 if(root.querySelector('.editor-lockbar')){
   setEditorLocked(true,view);
   return;
 }
 const bar=document.createElement('div');
 bar.className='editor-lockbar editor-locked';
 bar.innerHTML=`<div><strong>Section editor</strong><div class="status" id="editorStatus">Editing is locked. Click Edit Section before changing anything.</div></div><div class="row"><button class="btn gold" id="sectionEditBtn" type="button">✎ Edit Section</button><button class="btn" id="sectionSaveAllBtn" type="button" disabled>Save Changes</button><button class="btn" id="sectionCancelBtn" type="button">Cancel</button></div>`;
 root.insertBefore(bar,root.firstChild);
 bar.querySelector('#sectionEditBtn').addEventListener('click',()=>setEditorLocked(false,view));
 bar.querySelector('#sectionSaveAllBtn').addEventListener('click',saveSectionChanges);
 bar.querySelector('#sectionCancelBtn').addEventListener('click',()=>renderView(view));
 setEditorLocked(true,view);
}

function setEditorLocked(locked,view){
 const root=$('views'); if(!root)return;
 root.classList.toggle('editor-locked',locked);
 root.querySelectorAll('input,textarea,select').forEach(el=>{
   if(el.closest('.editor-lockbar'))return;
   el.disabled=locked;
 });
 root.querySelectorAll('button.btn').forEach(btn=>{
   if(btn.closest('.editor-lockbar'))return;
   const text=(btn.textContent||'').trim().toLowerCase();
   const isMutation=/^(save|upload|add|remove|delete|duplicate|set |use |copy path)/.test(text);
   if(isMutation)btn.disabled=locked;
 });
 root.querySelectorAll('.pill button,.icon.danger').forEach(btn=>{btn.disabled=locked});
 const bar=root.querySelector('.editor-lockbar');
 if(bar){bar.classList.toggle('editing',!locked);const st=bar.querySelector('#editorStatus');if(st)st.textContent=locked?'Editing is locked. Click Edit Section before changing anything.':'Editing enabled. Make your changes, then click Save Changes.';const edit=bar.querySelector('#sectionEditBtn');const all=bar.querySelector('#sectionSaveAllBtn');if(edit)edit.disabled=!locked;if(all)all.disabled=locked;}
}

async function saveSectionChanges(){
 const root=$('views');
 const saveButtons=[...root.querySelectorAll('button.btn:not(.gold) ,button.btn.gold')].filter(b=>b.id!=='sectionSaveAllBtn'&&/^(save|upload|set |use |copy path)/i.test((b.textContent||'').trim())&&!b.disabled);
 if(!saveButtons.length){toast('No section save action is available here.',true);return;}
 for(const b of saveButtons){try{b.click();await new Promise(r=>setTimeout(r,120))}catch(e){toast(e.message||String(e),true);return}}
 toast('All section changes saved ✓');
}

function viewOverview(){$('views').innerHTML=`<div class="grid three"><div class="card"><div class="stat">${STATE.research?.length||0}</div><div>Research projects</div></div><div class="card"><div class="stat">${(STATE.skills||[]).reduce((n,c)=>n+(c.skills||[]).length,0)}</div><div>Linked skills</div></div><div class="card"><div class="stat">${STATE.education?.length||0}</div><div>Education entries</div></div></div><div class="grid two" style="margin-top:16px"><div class="card"><h2>Quick actions</h2><div class="row"><button class="btn gold" onclick="renderView('research');openResearch()">+ Add research</button><button class="btn" onclick="renderView('media')">Open media library</button><button class="btn" onclick="renderView('appearance')">Tune appearance</button></div></div><div class="card"><h2>Security status</h2><p class="success">✓ GitHub token is session-only.</p><p class="success">✓ No token is stored in repository files.</p><p class="sub">${STATE.site?.lastUpdated?'Last content update: '+new Date(STATE.site.lastUpdated).toLocaleString(): 'No update timestamp yet.'}</p></div></div><div class="card" style="margin-top:16px"><h2>Editing model</h2><p class="sub">Public pages are separate: Research → project detail, Skills → skill detail. This keeps the portfolio clean while the dashboard stays organised.</p></div>`}
function formCard(title,body){return `<div class="card"><h2>${title}</h2>${body}</div>`}
function viewHome(){$('views').innerHTML=formCard('Home editor',`<p class="sub">Control the hero identity without changing the public structure. Keep the name concise and professional; the header cap treatment is controlled separately by the site design.</p><div class="grid two"><div class="field"><label>Name</label><input id="home_name" value="${attr(STATE.site.name)}"></div><div class="field"><label>Professional title</label><input id="home_title" value="${attr(STATE.site.professionalTitle)}"></div><div class="field"><label>Hero label</label><input id="home_label" value="${attr(STATE.site.heroLabel)}"></div><div class="field"><label>Hero tagline</label><input id="home_tag" value="${attr(STATE.site.heroTagline)}"></div><div class="field"><label>Primary button text</label><input id="home_btn1" value="${attr(STATE.site.primaryButtonText||'View Research')}"></div><div class="field"><label>Primary button link</label><input id="home_btn1l" value="${attr(STATE.site.primaryButtonLink||'research.html')}"></div><div class="field"><label>Secondary button text</label><input id="home_btn2" value="${attr(STATE.site.secondaryButtonText||'Download CV')}"></div><div class="field"><label>CV URL/path</label><input id="home_cv" value="${attr(STATE.site.cvUrl||STATE.cv?.url||'')}"></div></div><div class="field"><label>Hero description</label><textarea id="home_desc">${esc(STATE.site.heroDescription)}</textarea></div><div class="grid two"><div class="field"><label>Hero image path</label><input id="home_img" value="${attr(STATE.site.heroImage)}"></div><div class="field"><label>Show hero buttons</label><select id="home_show"><option value="yes" ${STATE.site.showButtons!==false?'selected':''}>Yes</option><option value="no" ${STATE.site.showButtons===false?'selected':''}>No</option></select></div></div><div class="notice">For the DNA/chemical artwork, use Appearance or Media Library. This keeps the Home editor focused on content and prevents accidental background distortion.</div><button class="btn gold" onclick="saveHome()">Save Home</button>`)}
async function saveHome(){Object.assign(STATE.site,{name:$('home_name').value.trim(),siteTitle:$('home_name').value.trim(),professionalTitle:$('home_title').value.trim(),heroLabel:$('home_label').value.trim(),heroTagline:$('home_tag').value.trim(),heroDescription:$('home_desc').value.trim(),heroImage:$('home_img').value.trim(),primaryButtonText:$('home_btn1').value.trim(),primaryButtonLink:$('home_btn1l').value.trim(),secondaryButtonText:$('home_btn2').value.trim(),cvUrl:$('home_cv').value.trim(),secondaryButtonLink:$('home_cv').value.trim(),showButtons:$('home_show').value==='yes'});await save('site','Update home content')}
function viewAbout(){$('views').innerHTML=formCard('About editor',`<div class="field"><label>Heading</label><input id="ab_h" value="${attr(STATE.about.heading)}"></div><div class="field"><label>Biography</label><textarea id="ab_b">${esc(STATE.about.biography)}</textarea></div><div class="field"><label>Profile image path</label><input id="ab_img" value="${attr(STATE.about.profileImage)}"></div><div class="grid two">${(STATE.about.cards||[]).map((c,i)=>`<div class="field"><label>Card ${i+1} label</label><input id="ab_l${i}" value="${attr(c.label)}"><label style="margin-top:6px">Value</label><input id="ab_v${i}" value="${attr(c.value)}"></div>`).join('')}</div><button class="btn gold" onclick="saveAbout()">Save About</button>`)}
async function saveAbout(){STATE.about.heading=$('ab_h').value.trim();STATE.about.biography=$('ab_b').value.trim();STATE.about.profileImage=$('ab_img').value.trim();STATE.about.cards=(STATE.about.cards||[]).map((c,i)=>({label:$('ab_l'+i).value.trim(),value:$('ab_v'+i).value.trim()}));await save('about','Update about')}
function viewPublications(){const pubs=[...(STATE.publications||[])];$('views').innerHTML=`<div class="toolbar" style="justify-content:space-between;margin-bottom:12px"><div class="sub">This is the dashboard editor. It does not open the public Publications page.</div><button class="btn gold" onclick="openPublication()">+ Add publication</button></div><div class="card table-wrap"><table class="table"><thead><tr><th>Publication</th><th>Year</th><th>Venue</th><th>DOI</th><th>Actions</th></tr></thead><tbody>${pubs.map((p,i)=>`<tr><td><strong>${esc(p.title)}</strong><div class="sub">${esc(p.authors||'')}</div></td><td>${esc(p.year)}</td><td>${esc(p.venue)}</td><td>${esc(p.doi||'—')}</td><td><div class="actions"><button class="icon" onclick="openPublication(${i})">Edit</button><button class="icon danger" onclick="deletePublication(${i})">Delete</button></div></td></tr>`).join('')}</tbody></table></div>`}
function openPublication(i){const p=i===undefined?{slug:'',title:'',year:'',type:'Journal Article',venue:'',doi:'',externalUrl:'',pdfUrl:'',authors:'',projectSlug:''}:STATE.publications[i];openModal(`<h2>${i===undefined?'Add':'Edit'} publication</h2><div class="grid two"><div class="field"><label>Title</label><textarea id="pub_title">${esc(p.title)}</textarea></div><div class="field"><label>Authors</label><textarea id="pub_authors">${esc(p.authors)}</textarea></div><div class="field"><label>Year</label><input id="pub_year" value="${attr(p.year)}"></div><div class="field"><label>Type</label><input id="pub_type" value="${attr(p.type)}"></div><div class="field"><label>Venue / journal</label><input id="pub_venue" value="${attr(p.venue)}"></div><div class="field"><label>DOI</label><input id="pub_doi" value="${attr(p.doi)}"></div><div class="field"><label>Authentic publication URL</label><input id="pub_ext" value="${attr(p.externalUrl)}"></div><div class="field"><label>PDF URL</label><input id="pub_pdf" value="${attr(p.pdfUrl)}"></div><div class="field"><label>Slug</label><input id="pub_slug" value="${attr(p.slug)}"></div><div class="field"><label>Linked project slug</label><input id="pub_project" value="${attr(p.projectSlug)}"></div></div><div class="modal-actions"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn gold" onclick="savePublication(${i===undefined?'null':i})">Save publication</button></div>`)}
async function savePublication(i){const p={slug:$('pub_slug').value.trim()||$('pub_title').value.trim().toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,''),title:$('pub_title').value.trim(),authors:$('pub_authors').value.trim(),year:$('pub_year').value.trim(),type:$('pub_type').value.trim(),venue:$('pub_venue').value.trim(),doi:$('pub_doi').value.trim(),externalUrl:$('pub_ext').value.trim(),pdfUrl:$('pub_pdf').value.trim(),projectSlug:$('pub_project').value.trim()};if(i===null)STATE.publications.push(p);else STATE.publications[i]=p;await save('publications','Update publication');closeModal();renderView('publications')}
async function deletePublication(i){if(confirm('Delete this publication?')){STATE.publications.splice(i,1);await save('publications','Delete publication');renderView('publications')}}
function viewResearch(){$('views').innerHTML=`<div class="toolbar" style="justify-content:space-between;margin-bottom:12px"><div class="sub">Every project gets its own public detail page with methods, results and authentic publication/PDF links.</div><button class="btn gold" onclick="openResearch()">+ Add Research</button></div><div class="card table-wrap"><table class="table"><thead><tr><th>Project</th><th>Category</th><th>Year</th><th>Links</th><th>Actions</th></tr></thead><tbody>${(STATE.research||[]).sort((a,b)=>(a.order??0)-(b.order??0)).map((r,i)=>`<tr><td><strong>${esc(r.title)}</strong><div class="sub">${esc(r.slug)}</div></td><td>${esc(r.category)}</td><td>${esc(r.year)}</td><td>${r.externalUrl?'Publication ':''}${r.pdfUrl?'PDF ':''}${r.githubUrl?'GitHub':''}</td><td><div class="actions"><button class="icon" onclick="openResearch(${i})">Edit</button><button class="icon" onclick="duplicateResearch(${i})">Duplicate</button><button class="icon danger" onclick="deleteResearch(${i})">Delete</button></div></td></tr>`).join('')}</tbody></table></div>`}
function mediaOptions(v=''){const imgs=STATE.images||[];return `<option value="">No image</option>`+imgs.filter(x=>x.type==='image').map(x=>`<option value="${attr(x.path)}" ${x.path===v?'selected':''}>${esc(x.name)}</option>`).join('')}
function openResearch(idx){const r=idx!==undefined?STATE.research[idx]:{slug:'',title:'',category:'',year:'',image:'',description:'',methods:'',tags:[],externalUrl:'',pdfUrl:'',githubUrl:'',featured:false,order:(STATE.research?.length||0)+1,publication:{journal:'',volume:'',pages:'',doi:'',year:''},results:[]};openModal(`<h2>${idx!==undefined?'Edit':'Add'} research project</h2><div class="grid two"><div class="field"><label>Title</label><input id="r_title" value="${attr(r.title)}"></div><div class="field"><label>Slug</label><input id="r_slug" value="${attr(r.slug)}" placeholder="unique-url-slug"></div><div class="field"><label>Category</label><input id="r_cat" value="${attr(r.category)}"></div><div class="field"><label>Year</label><input id="r_year" value="${attr(r.year)}"></div><div class="field"><label>Research image</label><select id="r_img">${mediaOptions(r.image)}</select></div><div class="field"><label>Tags, comma separated</label><input id="r_tags" value="${attr((r.tags||[]).join(', '))}"></div></div><div class="field"><label>Description</label><textarea id="r_desc">${esc(r.description)}</textarea></div><div class="field"><label>Methods</label><textarea id="r_methods">${esc(r.methods)}</textarea></div><div class="field"><label>Key results, one per line</label><textarea id="r_results">${esc((r.results||[]).join('\n'))}</textarea></div><h3>Publication metadata</h3><div class="grid three"><div class="field"><label>Journal</label><input id="r_journal" value="${attr(r.publication?.journal)}"></div><div class="field"><label>Volume / issue</label><input id="r_volume" value="${attr(r.publication?.volume)}"></div><div class="field"><label>Pages</label><input id="r_pages" value="${attr(r.publication?.pages)}"></div><div class="field"><label>DOI</label><input id="r_doi" value="${attr(r.publication?.doi)}"></div><div class="field"><label>Publication year</label><input id="r_py" value="${attr(r.publication?.year)}"></div></div><h3>Authentic resources</h3><div class="grid two"><div class="field"><label>Publication / external URL</label><input id="r_ext" value="${attr(r.externalUrl)}"></div><div class="field"><label>PDF URL</label><input id="r_pdf" value="${attr(r.pdfUrl)}"></div><div class="field"><label>GitHub URL</label><input id="r_gh" value="${attr(r.githubUrl)}"></div><div class="field"><label>Order</label><input id="r_order" type="number" value="${attr(r.order)}"></div></div><div class="modal-actions"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn gold" onclick="saveResearch(${idx===undefined?'null':idx})">Save project</button></div>`)}
async function saveResearch(idx){const old=idx===null?{}:STATE.research[idx];const r={slug:$('r_slug').value.trim()||$('r_title').value.trim().toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,''),title:$('r_title').value.trim(),category:$('r_cat').value.trim(),year:$('r_year').value.trim(),image:$('r_img').value,description:$('r_desc').value.trim(),methods:$('r_methods').value.trim(),results:$('r_results').value.split('\n').map(x=>x.trim()).filter(Boolean),tags:$('r_tags').value.split(',').map(x=>x.trim()).filter(Boolean),externalUrl:$('r_ext').value.trim(),pdfUrl:$('r_pdf').value.trim(),githubUrl:$('r_gh').value.trim(),featured:old.featured||false,order:Number($('r_order').value)||1,publication:{journal:$('r_journal').value.trim(),volume:$('r_volume').value.trim(),pages:$('r_pages').value.trim(),doi:$('r_doi').value.trim(),year:$('r_py').value.trim()}};if(idx===null)STATE.research.push(r);else STATE.research[idx]=r;await save('research','Update research project');closeModal();renderView('research')}
async function deleteResearch(i){if(confirm('Delete this project?')){STATE.research.splice(i,1);await save('research','Delete research project');renderView('research')}}
async function duplicateResearch(i){const r=JSON.parse(JSON.stringify(STATE.research[i]));r.slug=r.slug+'-copy';r.title+=' (Copy)';r.order=(STATE.research.length||0)+1;STATE.research.push(r);await save('research','Duplicate research project');renderView('research')}
function viewSkills(){$('views').innerHTML=`<div class="grid two"><div>${(STATE.skills||[]).map((c,i)=>`<div class="card" style="margin-bottom:12px"><div class="row" style="justify-content:space-between"><input style="background:transparent;border:0;color:white;font-weight:800;font-size:1rem" id="cat_${i}" value="${attr(c.category)}"><button class="icon danger" onclick="deleteSkillCat(${i})">Delete</button></div><div style="margin-top:8px">${(c.skills||[]).map((s,j)=>`<span class="pill">${esc(s)}<button onclick="removeSkill(${i},${j})">×</button></span>`).join('')}</div><div class="row" style="margin-top:10px"><input id="newskill_${i}" placeholder="Add skill"><button class="btn" onclick="addSkill(${i})">Add</button></div><button class="btn" style="margin-top:10px" onclick="saveSkillCat(${i})">Save category</button></div>`).join('')}<button class="btn gold" onclick="addSkillCat()">+ Add category</button></div><div class="card"><h2>Skill detail pages</h2><p class="sub">Every skill is linked to a separate page. Edit its summary, detailed explanation and evidence below.</p><div class="table-wrap"><table class="table"><thead><tr><th>Skill</th><th>Category</th><th>Action</th></tr></thead><tbody>${(STATE['skill-details']||[]).map((s,i)=>`<tr><td>${esc(s.name)}</td><td>${esc(s.category)}</td><td><button class="icon" onclick="openSkillDetail(${i})">Edit</button></td></tr>`).join('')}</tbody></table></div></div></div>`}
async function saveSkillCat(i){STATE.skills[i].category=$('cat_'+i).value.trim();await save('skills','Update skill category');renderView('skills')}
async function addSkill(i){const v=$('newskill_'+i).value.trim();if(!v)return;STATE.skills[i].skills=STATE.skills[i].skills||[];STATE.skills[i].skills.push(v);const exists=(STATE['skill-details']||[]).some(x=>x.name.toLowerCase()===v.toLowerCase());if(!exists){STATE['skill-details'].push({name:v,category:STATE.skills[i].category,summary:'',details:'',evidence:[]});await savePath(PATH['skill-details'],STATE['skill-details'],'Add skill detail')}await save('skills','Add skill')}
async function removeSkill(i,j){STATE.skills[i].skills.splice(j,1);await save('skills','Remove skill');renderView('skills')}
async function deleteSkillCat(i){if(confirm('Delete this category and its skills?')){STATE.skills.splice(i,1);await save('skills','Delete skill category');renderView('skills')}}
async function addSkillCat(){STATE.skills.push({category:'New Category',skills:[]});await save('skills','Add skill category');renderView('skills')}
function openSkillDetail(i){const s=STATE['skill-details'][i];openModal(`<h2>Edit skill detail</h2><div class="field"><label>Skill</label><input id="sd_name" value="${attr(s.name)}"></div><div class="field"><label>Category</label><input id="sd_cat" value="${attr(s.category)}"></div><div class="field"><label>Short summary</label><textarea id="sd_sum">${esc(s.summary)}</textarea></div><div class="field"><label>Detailed description</label><textarea id="sd_det">${esc(s.details)}</textarea></div><div class="field"><label>Evidence / examples, one per line</label><textarea id="sd_ev">${esc((s.evidence||[]).join('\n'))}</textarea></div><div class="modal-actions"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn gold" onclick="saveSkillDetail(${i})">Save</button></div>`)}
async function saveSkillDetail(i){STATE['skill-details'][i]={name:$('sd_name').value.trim(),category:$('sd_cat').value.trim(),summary:$('sd_sum').value.trim(),details:$('sd_det').value.trim(),evidence:$('sd_ev').value.split('\n').map(x=>x.trim()).filter(Boolean)};await savePath(PATH['skill-details'],STATE['skill-details'],'Update skill detail');closeModal();renderView('skills')}
function viewEducation(){$('views').innerHTML=`<div class="toolbar" style="justify-content:flex-end"><button class="btn gold" onclick="openEducation()">+ Add education</button></div><div class="card table-wrap"><table class="table"><thead><tr><th>Degree</th><th>Institution</th><th>Period</th><th>Actions</th></tr></thead><tbody>${(STATE.education||[]).map((e,i)=>`<tr><td>${esc(e.degree)}</td><td>${esc(e.institution)}</td><td>${esc([e.startDate,e.current?'Present':e.endDate].filter(Boolean).join(' – '))}</td><td><button class="icon" onclick="openEducation(${i})">Edit</button><button class="icon danger" onclick="deleteEducation(${i})">Delete</button></td></tr>`).join('')}</tbody></table></div>`}
function openEducation(i){const e=i===undefined?{degree:'',institution:'',location:'',startDate:'',endDate:'',current:false,description:'',logo:'',website:''}:STATE.education[i];openModal(`<h2>${i===undefined?'Add':'Edit'} education</h2><div class="grid two"><div class="field"><label>Degree</label><input id="e_deg" value="${attr(e.degree)}"></div><div class="field"><label>Institution</label><input id="e_inst" value="${attr(e.institution)}"></div><div class="field"><label>Location</label><input id="e_loc" value="${attr(e.location)}"></div><div class="field"><label>Start date</label><input id="e_start" value="${attr(e.startDate)}"></div><div class="field"><label>End date</label><input id="e_end" value="${attr(e.endDate)}"></div><div class="field switch"><input id="e_cur" type="checkbox" ${e.current?'checked':''}><label>Current</label></div></div><div class="field"><label>Description</label><textarea id="e_desc">${esc(e.description)}</textarea></div><div class="field"><label>Institution website</label><input id="e_web" value="${attr(e.website)}"></div><div class="modal-actions"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn gold" onclick="saveEducation(${i===undefined?'null':i})">Save</button></div>`)}
async function saveEducation(i){const e={degree:$('e_deg').value.trim(),institution:$('e_inst').value.trim(),location:$('e_loc').value.trim(),startDate:$('e_start').value.trim(),endDate:$('e_end').value.trim(),current:$('e_cur').checked,description:$('e_desc').value.trim(),logo:'',website:$('e_web').value.trim()};if(i===null)STATE.education.push(e);else STATE.education[i]=e;await save('education','Update education');closeModal();renderView('education')}
async function deleteEducation(i){if(confirm('Delete this entry?')){STATE.education.splice(i,1);await save('education','Delete education');renderView('education')}}
function viewContact(){$('views').innerHTML=formCard('Contact channels',`<div class="notice">For security and reliability, this GitHub Pages build does not include a public form backend. Use email and professional links. You can later connect a secure form service if needed.</div><div class="grid two"><div class="field"><label>Email</label><input id="ct_email" value="${attr(STATE.contact.email)}"></div><div class="field"><label>LinkedIn</label><input id="ct_li" value="${attr(STATE.contact.linkedin)}"></div><div class="field"><label>GitHub</label><input id="ct_gh" value="${attr(STATE.contact.github)}"></div><div class="field"><label>ResearchGate</label><input id="ct_rg" value="${attr(STATE.contact.researchgate)}"></div><div class="field"><label>ORCID</label><input id="ct_orcid" value="${attr(STATE.contact.orcid)}"></div></div><div class="field"><label>Intro</label><textarea id="ct_intro">${esc(STATE.contact.intro)}</textarea></div><button class="btn gold" onclick="saveContact()">Save contact</button>`)}
async function saveContact(){Object.assign(STATE.contact,{email:$('ct_email').value.trim(),linkedin:$('ct_li').value.trim(),github:$('ct_gh').value.trim(),researchgate:$('ct_rg').value.trim(),orcid:$('ct_orcid').value.trim(),intro:$('ct_intro').value.trim()});STATE.site.email=STATE.contact.email;STATE.site.linkedin=STATE.contact.linkedin;STATE.site.github=STATE.contact.github;await save('contact','Update contact');await save('site','Sync contact links')}
async function refreshImages(){try{const arr=await GH.listFolder('assets/images');STATE.images=(arr||[]).filter(x=>x.type==='file').map(x=>({name:x.name,path:x.path,type:/\.(png|jpe?g|gif|webp|svg)$/i.test(x.name)?'image':'file',url:x.download_url||''}))}catch{STATE.images=[]}}
function viewMedia(){refreshImages().then(()=>{$('views').innerHTML=`<div class="card"><h2>Media Library</h2><p class="sub">Save images once and reuse them anywhere. Each image has independent actions for portfolio background, dashboard background, copying its repository path, or using it as a content image.</p><div class="toolbar" style="justify-content:space-between;margin-top:12px"><div class="notice"><strong>Portfolio background:</strong> use the supplied scientific-background.png to preserve the DNA helix + 3D chemical-structure artwork exactly.</div><div class="row"><input id="mediaFile" type="file" accept="image/*"><button class="btn gold" onclick="uploadMedia()">Upload image</button></div></div></div><div class="media-grid" style="margin-top:16px">${STATE.images.map(x=>`<div class="media"><img src="${esc(x.url||x.path)}" alt=""><div class="meta"><strong>${esc(x.name)}</strong><br>${esc(x.path)}<div class="actions" style="margin-top:8px"><button class="icon" onclick="copyText('${attr(x.path)}')">Copy path</button><button class="icon" onclick="setPortfolioBackground('${attr(x.path)}')">Set portfolio background</button><button class="icon" onclick="setDashboardBackground('${attr(x.path)}')">Set dashboard background</button><button class="icon" onclick="useMediaForHome('${attr(x.path)}')">Use for Home image</button></div></div></div>`).join('')}</div>`;setTimeout(()=>setupSectionEditor('media'),0)})}
async function uploadMedia(){const f=$('mediaFile').files[0];if(!f)return toast('Choose an image first',true);if(f.size>8*1024*1024)return toast('For GitHub Pages, keep images under 8 MB.',true);const b=await fileBase64(f);const path='assets/images/'+safeFileName(f.name);await GH.putBinaryBase64(path,b,'Upload media');toast('Image uploaded ✓');viewMedia()}
function safeFileName(n){return n.toLowerCase().replace(/[^a-z0-9._-]+/g,'-')}
function fileBase64(f){return new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(String(r.result).split(',')[1]);r.onerror=rej;r.readAsDataURL(f)})}
function copyText(t){navigator.clipboard?.writeText(t);toast('Path copied')}
async function setPortfolioBackground(path){STATE.appearance.backgroundImage=path;STATE.appearance.backgroundFit='cover';STATE.appearance.backgroundSize='cover';STATE.appearance.sectionBackgroundEnabled=true;await save('appearance','Set portfolio background image');toast('Portfolio background set ✓');renderView('appearance')}
async function setDashboardBackground(path){STATE.appearance.dashboardBackgroundImage=path;await save('appearance','Set dashboard background image');applyDashboardTheme();toast('Dashboard background set ✓');renderView('appearance')}
async function useMediaForHome(path){STATE.site.heroImage=path;await save('site','Set Home hero image');toast('Home image updated ✓');renderView('home')}
function applyDashboardTheme(){const t=JSON.parse(localStorage.getItem('dashboard-theme-v1')||'{}');const a=STATE.appearance||{};const r=document.documentElement;[['bg','--bg'],['panel','--panel'],['gold','--gold'],['text','--text'],['font','--dash-font']].forEach(([k,v])=>{if(t[k])r.style.setProperty(v,t[k])});if(t.font)document.body.style.fontFamily=t.font;else if(a.dashboardFont)document.body.style.fontFamily=a.dashboardFont;const bg=a.dashboardBackgroundImage||t.backgroundImage||'';if(bg){document.body.style.backgroundImage=`linear-gradient(rgba(11,11,12,.86),rgba(11,11,12,.90)),url('../${bg.replace(/^\//,'')}')`;document.body.style.backgroundSize='cover';document.body.style.backgroundPosition='center';document.body.style.backgroundAttachment='fixed'}else document.body.style.backgroundImage='';}
function saveDashboardDesign(){const t={bg:$('db_bg').value,panel:$('db_panel').value,gold:$('db_gold').value,text:$('db_text').value,font:$('db_font').value,backgroundImage:$('db_bg_image').value.trim()};localStorage.setItem('dashboard-theme-v1',JSON.stringify(t));STATE.appearance.dashboardFont=t.font;STATE.appearance.dashboardBackgroundImage=t.backgroundImage;save('appearance','Update dashboard design').then(()=>{applyDashboardTheme();toast('Dashboard design saved ✓');renderView('appearance')}).catch(e=>toast(e.message,true))}
function viewAppearance(){const a=STATE.appearance||{};const dt=JSON.parse(localStorage.getItem('dashboard-theme-v1')||'{}');const fonts=`<option value="Inter,system-ui,-apple-system,&quot;Segoe UI&quot;,sans-serif">Inter</option><option value="Georgia,&quot;Times New Roman&quot;,serif">Georgia</option><option value="Garamond,&quot;EB Garamond&quot;,serif">Garamond</option><option value="Baskerville,&quot;Libre Baskerville&quot;,serif">Baskerville</option><option value="Palatino,&quot;Book Antiqua&quot;,serif">Palatino</option><option value="&quot;Book Antiqua&quot;,Palatino,serif">Book Antiqua</option><option value="Cambria,Georgia,serif">Cambria</option><option value="&quot;Times New Roman&quot;,Times,serif">Times New Roman</option><option value="Didot,&quot;Bodoni MT&quot;,serif">Didot</option><option value="&quot;Bodoni MT&quot;,Didot,serif">Bodoni</option><option value="Cochin,Georgia,serif">Cochin</option><option value="&quot;Century Schoolbook&quot;,Georgia,serif">Century Schoolbook</option><option value="Constantia,Georgia,serif">Constantia</option><option value="Perpetua,Georgia,serif">Perpetua</option><option value="Rockwell,&quot;Courier New&quot;,serif">Rockwell</option><option value="&quot;Gill Sans&quot;,Arial,sans-serif">Gill Sans</option><option value="Avenir,&quot;Segoe UI&quot;,sans-serif">Avenir</option><option value="&quot;Helvetica Neue&quot;,Arial,sans-serif">Helvetica Neue</option><option value="Arial,Helvetica,sans-serif">Arial</option><option value="Verdana,Geneva,sans-serif">Verdana</option><option value="&quot;Trebuchet MS&quot;,Arial,sans-serif">Trebuchet MS</option><option value="&quot;Century Gothic&quot;,Arial,sans-serif">Century Gothic</option><option value="Futura,&quot;Trebuchet MS&quot;,sans-serif">Futura</option><option value="&quot;Franklin Gothic Medium&quot;,Arial,sans-serif">Franklin Gothic</option><option value="Optima,&quot;Segoe UI&quot;,sans-serif">Optima</option><option value="Tahoma,Arial,sans-serif">Tahoma</option><option value="&quot;Lucida Sans&quot;,Arial,sans-serif">Lucida Sans</option><option value="&quot;Courier Prime&quot;,&quot;Courier New&quot;,monospace">Courier Prime</option><option value="Consolas,&quot;Courier New&quot;,monospace">Consolas</option><option value="Monaco,Consolas,monospace">Monaco</option>`;$('views').innerHTML=`<div class="card"><h2>Portfolio Background — Primary Control</h2><p class="sub">Control the exact scientific background across the portfolio. The supplied DNA + 3D chemical-structure image remains the same; only fit, position, opacity and overlays change.</p><div class="notice"><strong>Current portfolio background:</strong> ${esc(a.backgroundImage||'assets/images/scientific-background.png')}</div><div class="grid two"><div class="field"><label>Background image path</label><input id="ap_img" value="${attr(a.backgroundImage||'assets/images/scientific-background.png')}"><small class="sub">Choose an image from Media Library → Set portfolio background.</small></div><div class="field"><label>Opacity (0–1)</label><input id="ap_op" type="number" min="0" max="1" step="0.01" value="${attr(a.backgroundOpacity??0.26)}"></div><div class="field"><label>Position</label><select id="ap_pos">${['center','top','bottom','left','right','center top','center bottom','left center','right center'].map(x=>`<option ${a.backgroundPosition===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Fit / automatic sizing</label><select id="ap_fit"><option value="cover" ${a.backgroundFit!=='contain'?'selected':''}>Cover — automatic full-section fit</option><option value="contain" ${a.backgroundFit==='contain'?'selected':''}>Contain — show full image</option></select></div><div class="field"><label>Gradient angle</label><input id="ap_ang" value="${attr(a.gradientAngle||'135deg')}"></div><div class="field"><label>Section background</label><select id="ap_section"><option value="all" ${a.sectionBackgroundEnabled!==false?'selected':''}>Use background throughout portfolio</option><option value="off" ${a.sectionBackgroundEnabled===false?'selected':''}>Disable section background</option></select></div></div><div class="row"><button class="btn gold" onclick="saveAppearance()">Save portfolio background</button><button class="btn" onclick="renderView('media')">Choose from Media Library</button></div></div><div class="grid two" style="margin-top:16px"><div class="card"><h2>Dashboard Design</h2><p class="sub">Dashboard-only appearance; never shown publicly.</p><div class="grid two"><div class="field"><label>Dashboard background color</label><input id="db_bg" type="color" value="${attr(dt.bg||'#0B0B0C')}"></div><div class="field"><label>Panel background</label><input id="db_panel" type="color" value="${attr(dt.panel||'#121214')}"></div><div class="field"><label>Button / accent</label><input id="db_gold" type="color" value="${attr(dt.gold||'#D7B449')}"></div><div class="field"><label>Dashboard text color</label><input id="db_text" type="color" value="${attr(dt.text||'#F3F0E8')}"></div></div><div class="field"><label>Dashboard background image</label><input id="db_bg_image" value="${attr(a.dashboardBackgroundImage||'')}"><small class="sub">Or use Media Library → Set dashboard background.</small></div><div class="field"><label>Dashboard font</label><select id="db_font">${fonts}</select></div><div class="row"><button class="btn gold" onclick="saveDashboardDesign()">Save dashboard design</button><button class="btn" onclick="renderView('media')">Choose image</button></div></div><div class="card"><h2>Typography — 30 Premium Font Presets</h2><p class="sub">Use the same font system across the portfolio and dashboard. Browser-safe fallbacks are included.</p><div class="field"><label>Portfolio + dashboard font</label><select id="ap_font">${fonts}</select></div><div class="grid three"><div class="field"><label>Heading weight</label><select id="ap_weight">${[400,500,600,700,800,900].map(x=>`<option value="${x}" ${String(a.headingWeight||700)===String(x)?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Card radius (px)</label><input id="ap_radius" type="number" min="0" max="40" value="${attr(a.cardRadius||16)}"></div><div class="field"><label>Button radius (px)</label><input id="ap_btn_radius" type="number" min="0" max="40" value="${attr(a.buttonRadius||10)}"></div><div class="field"><label>Letter spacing</label><input id="ap_letter" value="${attr(a.letterSpacing||'0px')}"></div><div class="field"><label>Line height</label><input id="ap_line" value="${attr(a.lineHeight||'1.65')}"></div><div class="field"><label>Content max width</label><input id="ap_width" value="${attr(a.contentMaxWidth||'1180px')}"></div></div></div></div><div class="card" style="margin-top:16px"><h2>Advanced visual controls</h2><div class="grid three"><div class="field"><label>Card style</label><select id="ap_card"><option value="soft">Soft</option><option value="glass">Glass</option><option value="flat">Flat</option><option value="outline">Outline</option><option value="elevated">Elevated</option></select></div><div class="field"><label>Shadow strength</label><input id="ap_shadow" type="range" min="0" max="1" step="0.05" value="${attr(a.shadowStrength??0.18)}"></div><div class="field"><label>Section spacing</label><input id="ap_spacing" value="${attr(a.sectionSpacing||'6rem')}"></div><div class="field"><label>Primary button background</label><input id="color_buttonBackground" type="color" value="${attr(a.buttonBackground||'#E9C46A')}"></div><div class="field"><label>Primary button text</label><input id="color_buttonText" type="color" value="${attr(a.buttonText||'#14100A')}"></div><div class="field"><label>Button border</label><input id="color_buttonBorder" type="color" value="${attr(a.buttonBorder||'#C9A227')}"></div></div><h3>Portfolio color system</h3><div class="color-row">${[['primary','Primary'],['secondary','Secondary / Gold'],['accent','Accent'],['background','Light background'],['surface','Surface'],['text','Text'],['textSecondary','Secondary text'],['darkBackground','Dark background'],['darkSurface','Dark surface'],['darkText','Dark text']].map(([k,l])=>`<div class="field"><label>${l}</label><div class="color-field"><input type="color" id="color_${k}" value="${attr(a.colors?.[k]||'#000000')}"></div></div>`).join('')}</div><div class="row"><button class="btn gold" onclick="saveAppearance()">Save all appearance settings</button><button class="btn" onclick="renderView('overview')">Back to Overview</button></div></div>`;const af=a.font||'Inter,system-ui,-apple-system,"Segoe UI",sans-serif';$('ap_font').value=af;$('db_font').value=a.dashboardFont||dt.font||af;$('ap_card').value=a.cardStyle||'soft';}
async function saveAppearance(){const a=STATE.appearance||{};a.font=$('ap_font').value;a.dashboardFont=$('db_font').value;a.headingWeight=Number($('ap_weight').value);a.cardRadius=$('ap_radius').value;a.buttonRadius=$('ap_btn_radius').value;a.letterSpacing=$('ap_letter').value.trim();a.lineHeight=$('ap_line').value.trim();a.contentMaxWidth=$('ap_width').value.trim();a.backgroundImage=$('ap_img').value.trim()||'assets/images/scientific-background.png';a.backgroundOpacity=Math.max(0,Math.min(1,Number($('ap_op').value)));a.backgroundPosition=$('ap_pos').value;a.backgroundFit=$('ap_fit').value;a.backgroundSize=a.backgroundFit;a.gradientAngle=$('ap_ang').value.trim()||'135deg';a.sectionBackgroundEnabled=$('ap_section').value==='all';a.gradientEnabled=true;a.cardStyle=$('ap_card').value;a.shadowStrength=Number($('ap_shadow').value);a.sectionSpacing=$('ap_spacing').value.trim()||'6rem';a.colors=a.colors||{};['primary','secondary','accent','background','surface','text','textSecondary','darkBackground','darkSurface','darkText'].forEach(k=>{a.colors[k]=$('color_'+k).value});a.buttonBackground=$('color_buttonBackground').value;a.buttonText=$('color_buttonText').value;a.buttonBorder=$('color_buttonBorder').value;await save('appearance','Update appearance');applyDashboardTheme();toast('Portfolio appearance saved ✓');renderView('appearance')}
function viewNavigation(){
 const items=(STATE.site.nav.items||[]).slice().sort((a,b)=>(a.order??0)-(b.order??0));
 const menu=(STATE.site.profileMenuItems||[]).slice().sort((a,b)=>(a.order??0)-(b.order??0));
 $('views').innerHTML=formCard('Navigation & profile menu',`<p class="sub">The public header never exposes the dashboard. The profile-photo menu contains only the items you choose here. You can add future items; each custom item opens its own clean detail page.</p><h3 style="margin-top:20px">Main navigation</h3><div class="table-wrap"><table class="table"><thead><tr><th>Order</th><th>Label</th><th>URL</th><th>Visible</th></tr></thead><tbody>${items.map((n,i)=>`<tr><td><input style="width:60px;background:#0d0d0f;border:1px solid #333;color:white;padding:6px;border-radius:6px" id="nav_o${i}" type="number" value="${attr(n.order)}"></td><td><input id="nav_l${i}" value="${attr(n.label)}"></td><td><input id="nav_h${i}" value="${attr(n.href)}"></td><td><input id="nav_v${i}" type="checkbox" ${n.visible!==false?'checked':''}></td></tr>`).join('')}</tbody></table></div><button class="btn gold" style="margin-top:12px" onclick="saveNavigation()">Save navigation</button><h3 style="margin-top:30px">Profile-photo menu</h3><p class="sub">Current items: Settings, CV &amp; Documents, Contact. Add a custom item when you need one later.</p><div id="profileMenuEditor">${menu.map((n,i)=>`<div class="card" style="margin-top:10px"><div class="grid two"><div class="field"><label>Label</label><input id="pm_l${i}" value="${attr(n.label)}"></div><div class="field"><label>Link / page</label><input id="pm_h${i}" value="${attr(n.href)}"></div><div class="field"><label>Type</label><select id="pm_t${i}"><option value="system" ${n.type==='system'?'selected':''}>System page</option><option value="external" ${n.type==='external'?'selected':''}>File / external link</option><option value="anchor" ${n.type==='anchor'?'selected':''}>Portfolio section</option><option value="custom" ${n.type==='custom'?'selected':''}>Custom detail page</option></select></div><div class="field"><label>Order</label><input id="pm_o${i}" type="number" value="${attr(n.order??i)}"></div></div>${n.type==='custom'?`<div class="field"><label>Page title</label><input id="pm_title${i}" value="${attr(n.title||n.label||'')}"></div><div class="field"><label>Short description</label><textarea id="pm_desc${i}">${esc(n.description||'')}</textarea></div><div class="field"><label>Detailed content</label><textarea id="pm_content${i}" style="min-height:180px">${esc(n.content||'')}</textarea></div>`:''}<div class="row"><label class="switch"><input id="pm_v${i}" type="checkbox" ${n.visible!==false?'checked':''}> Visible</label>${n.id && !['settings','cv-documents','contact'].includes(n.id)?`<button class="btn" onclick="removeProfileMenuItem(${i})">Remove</button>`:''}</div></div>`).join('')}</div><div class="row" style="margin-top:12px"><button class="btn" onclick="addProfileMenuItem()">+ Add profile-menu item</button><button class="btn gold" onclick="saveProfileMenu()">Save profile menu</button></div>`)
}
async function saveNavigation(){const items=[...STATE.site.nav.items].sort((a,b)=>(a.order??0)-(b.order??0));items.forEach((n,i)=>{n.order=Number($('nav_o'+i).value)||i;n.label=$('nav_l'+i).value.trim();n.href=$('nav_h'+i).value.trim();n.visible=$('nav_v'+i).checked});STATE.site.nav.items=items;await save('site','Update navigation')}
function addProfileMenuItem(){STATE.site.profileMenuItems=STATE.site.profileMenuItems||[];STATE.site.profileMenuItems.push({id:'custom-'+Date.now(),label:'New item',title:'New item',description:'',content:'',href:'profile-menu-detail.html?item=new-item',type:'custom',visible:true,order:STATE.site.profileMenuItems.length});viewNavigation()}
function removeProfileMenuItem(i){const items=STATE.site.profileMenuItems||[];const x=items[i];if(x && ['settings','cv-documents','contact'].includes(x.id))return toast('Core menu items cannot be removed here.',true);items.splice(i,1);STATE.site.profileMenuItems=items;viewNavigation()}
async function saveProfileMenu(){const items=[...(STATE.site.profileMenuItems||[])].sort((a,b)=>(a.order??0)-(b.order??0));items.forEach((n,i)=>{n.label=$('pm_l'+i).value.trim();n.href=$('pm_h'+i).value.trim();n.type=$('pm_t'+i).value;n.order=Number($('pm_o'+i).value)||i;n.visible=$('pm_v'+i).checked;if(n.type==='custom'){n.title=$('pm_title'+i)?.value.trim()||n.label;n.description=$('pm_desc'+i)?.value.trim()||'';n.content=$('pm_content'+i)?.value.trim()||'';}if(n.type==='custom' && (!n.href || n.href.startsWith('profile-menu-detail.html?item=new-item'))){n.href=`profile-menu-detail.html?item=${encodeURIComponent((n.label||'item').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,''))}`}});STATE.site.profileMenuItems=items;await save('site','Update profile-photo menu')}
function viewCustomSections(){
 const items=[...(STATE.custom||[])].sort((a,b)=>(a.order??0)-(b.order??0));
 $('views').innerHTML=`<div class="card"><h2>Your custom portfolio sections</h2><p class="sub">These sections are optional and never appear until you enable them. You can add text, choose light/dark presentation, reuse an image from Media Library, and reorder them.</p><div id="customList">${items.map((x,i)=>`<div class="card" style="margin-top:12px"><div class="grid two"><div class="field"><label>Eyebrow</label><input id="cs_e${i}" value="${attr(x.eyebrow||'ADDITIONAL')}"></div><div class="field"><label>Title</label><input id="cs_t${i}" value="${attr(x.title||'New section')}"></div><div class="field"><label>Theme</label><select id="cs_th${i}"><option value="light" ${x.theme!=='dark'?'selected':''}>Light</option><option value="dark" ${x.theme==='dark'?'selected':''}>Dark</option></select></div><div class="field"><label>Order</label><input id="cs_o${i}" type="number" value="${attr(x.order??i)}"></div></div><div class="field"><label>Image path (optional)</label><input id="cs_i${i}" value="${attr(x.image||'')}"></div><div class="field"><label>Content</label><textarea id="cs_b${i}" style="min-height:150px">${esc(x.body||'')}</textarea></div><div class="row"><label class="switch"><input id="cs_v${i}" type="checkbox" ${x.visible!==false?'checked':''}> Visible</label><button class="btn danger" onclick="removeCustomSection(${i})">Remove</button></div></div>`).join('')}</div><div class="row" style="margin-top:14px"><button class="btn" onclick="addCustomSection()">+ Add section</button><button class="btn gold" onclick="saveCustomSections()">Save custom sections</button></div></div>`;
}
function addCustomSection(){STATE.custom=STATE.custom||[];STATE.custom.push({id:'section-'+Date.now(),eyebrow:'ADDITIONAL',title:'New section',body:'',theme:'light',image:'',visible:true,order:STATE.custom.length});viewCustomSections()}
function removeCustomSection(i){STATE.custom.splice(i,1);viewCustomSections()}
async function saveCustomSections(){const items=[...(STATE.custom||[])].sort((a,b)=>(a.order??0)-(b.order??0));items.forEach((x,i)=>{x.eyebrow=$('cs_e'+i).value.trim();x.title=$('cs_t'+i).value.trim();x.theme=$('cs_th'+i).value;x.order=Number($('cs_o'+i).value)||i;x.image=$('cs_i'+i).value.trim();x.body=$('cs_b'+i).value.trim();x.visible=$('cs_v'+i).checked});STATE.custom=items;await save('custom','Update custom portfolio sections')}

function viewLanguages(){const l=STATE.languages||{default:'en',enabled:['en','de','bn','es','it']};$('views').innerHTML=formCard('Language settings',`<div class="notice">The interface uses curated built-in translations for English, German, Bangla, Spanish and Italian. Portfolio content is kept in your content files; for academic accuracy, enter your own translated project text rather than sending unpublished research to an external translation API.</div><div class="field"><label>Default language</label><select id="lang_default">${['en','de','bn','es','it'].map(x=>`<option value="${x}" ${l.default===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Enabled languages</label>${['en','de','bn','es','it'].map(x=>`<label class="pill"><input type="checkbox" id="lang_${x}" ${l.enabled.includes(x)?'checked':''}> ${x.toUpperCase()}</label>`).join('')}</div><button class="btn gold" onclick="saveLanguages()">Save languages</button>`)}
async function saveLanguages(){const enabled=['en','de','bn','es','it'].filter(x=>$('lang_'+x).checked);if(!enabled.includes($('lang_default').value))enabled.unshift($('lang_default').value);STATE.languages={default:$('lang_default').value,enabled:[...new Set(enabled)]};await save('languages','Update language settings')}
function viewCV(){const c=STATE.cv||{};$('views').innerHTML=`<div class="grid two"><div class="card"><h2>CV file</h2><p class="sub">Upload a revised PDF whenever you update your CV. The public CV buttons use this path.</p><input id="cvFile" type="file" accept="application/pdf"><button class="btn gold" style="margin-top:10px" onclick="uploadCV()">Upload new CV PDF</button><div class="field"><label>Current CV path / URL</label><input id="cv_url" value="${attr(c.url||'')}"></div><button class="btn" onclick="saveCVUrl()">Save path</button><div class="field"><label>Editable CV source</label><p class="sub">Download the editable DOCX, revise it in Word/LibreOffice, export a new PDF, then upload that PDF above.</p><a class="btn" href="../assets/files/Fahad_Badsha_Shamim_CV_Editable.docx" download>Download editable CV (.docx)</a></div></div><div class="card"><h2>Cover Letter</h2><div class="field"><label>Editable cover-letter text</label><textarea id="cv_cl" style="min-height:360px">${esc(c.coverLetterText||'')}</textarea></div><div class="row"><button class="btn gold" onclick="saveCVMeta()">Save cover letter text</button><a class="btn" href="../assets/files/cover-letter.pdf" download>Download PDF</a><a class="btn" href="../assets/files/cover-letter-editable.docx" download>Editable DOCX</a></div></div></div><div class="card" style="margin-top:16px"><h2>CV profile metadata</h2><div class="field"><label>Profile summary</label><textarea id="cv_sum">${esc(c.profileSummary||'')}</textarea></div><div class="field"><label>Editable notes</label><textarea id="cv_notes">${esc(c.editableNotes||'')}</textarea></div><button class="btn gold" onclick="saveCVMeta()">Save CV details</button></div>`}
async function uploadCV(){const f=$('cvFile').files[0];if(!f)return toast('Choose a PDF',true);if(f.type!=='application/pdf')return toast('Only PDF is accepted.',true);if(f.size>10*1024*1024)return toast('Keep CV PDF under 10 MB.',true);const b=await fileBase64(f);const path='assets/files/cv.pdf';await GH.putBinaryBase64(path,b,'Update CV PDF');STATE.cv.url=path;STATE.cv.fileName=f.name;STATE.cv.lastUpdated=new Date().toISOString();await save('cv','Update CV metadata');STATE.site.cvUrl=path;STATE.site.secondaryButtonLink=path;await save('site','Update CV link');renderView('cv')}
async function saveCVUrl(){STATE.cv.url=$('cv_url').value.trim();STATE.site.cvUrl=STATE.cv.url;STATE.site.secondaryButtonLink=STATE.cv.url;await save('cv','Update CV path');await save('site','Update CV link')}
async function saveCVMeta(){STATE.cv.profileSummary=$('cv_sum').value.trim();STATE.cv.editableNotes=$('cv_notes').value.trim();if($('cv_cl'))STATE.cv.coverLetterText=$('cv_cl').value.trim();await save('cv','Update CV metadata and cover letter')}
function viewSecurity(){$('views').innerHTML=`<div class="grid two"><div class="card"><h2>GitHub connection</h2><p class="success">Token is stored only in sessionStorage for this browser session.</p><p class="sub">Repository configuration is stored separately. Disconnect before using a shared computer.</p><button class="btn danger" onclick="disconnectGH()">Disconnect & clear token</button></div><div class="card"><h2>Dashboard password</h2><p class="sub">Change the client-side password. This is an additional gate, not server-side authentication.</p><button class="btn gold" onclick="changePassword()">Change password</button></div></div><div class="card" style="margin-top:16px"><h2>Security checklist</h2><ul><li>Use a fine-grained token limited to this repository.</li><li>Grant only Contents: Read and write (and required metadata read-only).</li><li>Use a short token expiry such as 7–30 days.</li><li>Never paste the token into portfolio files or screenshots.</li><li>Lock the dashboard and revoke the token when finished.</li><li>Do not use the dashboard on an untrusted/shared browser.</li></ul></div>`}
function disconnectGH(){if(confirm('Disconnect this browser from GitHub?')){GH.clear();lock()}}
async function changePassword(){openModal(`<h2>Change password</h2><div class="field"><label>Current password</label><input id="oldpw" type="password"></div><div class="field"><label>New password (10+ characters)</label><input id="newpw" type="password"></div><div class="field"><label>Confirm</label><input id="newpw2" type="password"></div><div class="modal-actions"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn gold" onclick="savePasswordChange()">Change</button></div>`)}
async function savePasswordChange(){const d=STATE.access||{};const old=$('oldpw').value,newp=$('newpw').value;if(newp.length<10||newp!==$('newpw2').value)return toast('New passwords must match and be 10+ characters.',true);const oldHash=d.kdf==='PBKDF2'?await pbkdf2(old,d.salt,d.iterations||150000):await sha256(old);if(oldHash!==d.passwordHash)return toast('Current password is incorrect.',true);const salt=randHex();STATE.access={passwordHash:await pbkdf2(newp,salt),salt,kdf:'PBKDF2',iterations:150000,version:4};await savePath(PATH.access,STATE.access,'Change dashboard password');closeModal();toast('Password changed ✓')}
applyDashboardTheme();
applyDashLang();
